-- Power Forms packages (Kieran, Oct 2026): a named set of forms, e.g.
-- "Initial Clearance Forms", sent to a family as ONE link. Staff can leave
-- forms out when sending (or send one form on its own, as before). Each form
-- in a package still comes back, is reviewed and saved as its own request.
-- routes/powerForms.js. Safe to run more than once.

CREATE TABLE IF NOT EXISTS "PowerFormPackages" (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  template_ids JSONB NOT NULL DEFAULT '[]',  -- the forms, in order
  archived BOOLEAN NOT NULL DEFAULT false,
  created_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by TEXT,
  updated_at TIMESTAMPTZ
);

-- One per package sent: the link (only its SHA-256), its expiry and the
-- date-of-birth lockout, shared by the forms in it.
CREATE TABLE IF NOT EXISTS "PowerFormPackets" (
  id SERIAL PRIMARY KEY,
  token_hash TEXT NOT NULL UNIQUE,
  patient_id UUID NOT NULL REFERENCES "Patients"(id) ON DELETE CASCADE,
  package_id INTEGER REFERENCES "PowerFormPackages"(id),
  name TEXT NOT NULL,
  recipient TEXT,
  expires_at TIMESTAMPTZ NOT NULL,
  created_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  opened_at TIMESTAMPTZ,
  failed_checks INTEGER NOT NULL DEFAULT 0,
  locked_until TIMESTAMPTZ
);

-- A form sent in a package has no link of its own (the package's opens it).
ALTER TABLE "PowerFormRequests" ADD COLUMN IF NOT EXISTS packet_id INTEGER REFERENCES "PowerFormPackets"(id) ON DELETE SET NULL;
ALTER TABLE "PowerFormRequests" ALTER COLUMN token_hash DROP NOT NULL;
CREATE INDEX IF NOT EXISTS power_form_requests_packet ON "PowerFormRequests" (packet_id);

-- Kieran's Initial Clearance Forms (Oct 2026), built from the paper forms he
-- sent, and the package that sends them as one link. Added only if a form or
-- package with the same name isn't there yet, so edits made later in the
-- builder are kept if this runs again.
INSERT INTO "PowerFormTemplates" (name, intro, fields, created_by)
SELECT $pf$Attendance Policies$pf$, $pf$The Kidz Lounge Related Service, LLC is committed to providing all of our clients with exceptional and consistent care. We believe that your commitment to your child's therapy schedule is essential to their progress and development. We thank you in advance for your cooperation and attention to our attendance policy.$pf$, $pf$[{"id":"att_health","type":"heading","label":"Health","help":"Please understand that it is your responsibility to consult a physician regarding your child's participation in all programs and treatments prior to attending. By signing this you believe that your child is in good health and in proper physical condition to participate in such activities. It is your responsibility to inform your child's therapist, of any injuries and/or limitations that might affect their ability to participate.","required":false},{"id":"att_sickness","type":"heading","label":"Sickness Policy","help":"Help and cooperation is required in order to maintain a healthy environment. Please notify your provider as soon as possible if your child appears sick. If your child has experienced a fever, vomiting and/or diarrhea, he/she should not return to therapy until 24 hours have passed since the last episode of the same.\n\nChildren will not be seen if any of the following are present:\n• Fever over 100.3\n• Continual runny nose\n• Too ill or uncomfortable to function in the therapy setting\n• Thick or discolored nasal discharge\n• Excessive sneezing or mucus-producing cough\n• Diarrhea or vomiting\n• Severe cough, mucus-producing cough or trouble breathing\n• Rash/ Infected skin patches\n• Conjunctivitis (pink eye)\n• Sore throat","required":false},{"id":"att_cancel","type":"heading","label":"Cancellations","help":"Please notify your provider 24 hours prior to a scheduled appointment if you need to cancel for any reason. Please note that excessive cancellations, LATE cancellations (day of/less than 24 hours) will result in your child switching to a flex schedule (see below).","required":false},{"id":"att_noshow","type":"heading","label":"No Shows","help":"We understand that emergencies happen but after 2 no shows within 1 month your child will be switched to a flex schedule. Please be considerate of your therapist's time and schedule.\n\nMake-ups will be given based upon availability and be given according to your child's therapy mandate. No makeups will be given for no shows.","required":false},{"id":"att_flex","type":"heading","label":"Flex Schedule","help":"The flex schedule allows more flexibility for families whose schedules change week to week. This can be due to medical appointments or other circumstances in which regular appointment days and times are challenging. When on the flex schedule, there is no guarantee of the availability of your provider's specific day or time.\n\nYour child will be switched to a 'Flex Schedule' for the following reasons\n- Excessive Cancellations\n- Attendance Requirement - Your child must attend at least 80% of their scheduled sessions in a 3-month period to keep their assigned day and time\n    Examples (within a 3 month period):\n    1x/week (12 sessions/3 months) → MUST attend at least 10 (allowed 2 cancellations)\n    2x/week (24 sessions/3 months) → MUST attend at least 20 (allowed 4 cancellations)\n    3x/week (36 sessions/3 months) → MUST attend at least 30 (allowed 6 cancellations)\n• Two No shows in a 1 month period may result in immediate Flex Schedule\n    ★ NOTE: After 2 months, attendance will be reviewed\n    → If below 80%, a warning will be issued\n    → At the end of 3 months: If attendance is still below 80%, your child may be moved to a Flex Schedule.\n\nWe try our best to work with you. If your assigned time/day no longer works, please let us know and we will try our best to accommodate. Consistent attendance is essential for your child's progress.","required":false},{"id":"att_additional","type":"heading","label":"Additional attendance policies","help":"★ Any changes to a client's physical status (recent extended hospitalizations, surgery etc) - a new prescription will be needed and/or a doctor's note to return (please check with the front desk).\n★ Scheduled absences of 3 weeks or greater due to travel etc - clients appointment day/time will not be held.","required":false},{"id":"att_sign","type":"heading","label":"Attendance Policies","help":"★ Please sign and return to The Kidz Lounge\n\nBy signing I certify that I have reviewed and agree to The Kidz Lounge Attendance Policies. I understand that excessive cancellations and/or no shows may result in termination of services or a switch to a flex schedule.","required":false},{"id":"att_immunizations","type":"yesno","label":"To the best of my knowledge I certify that my child's immunizations are up to date.","help":"(we are obligated to be aware of children who are not vaccinated in order to notify you of an outbreak)","required":true},{"id":"att_child_name","type":"text","label":"Child's Name","help":null,"required":true,"prefill":"child_name"},{"id":"att_child_dob","type":"date","label":"Date of Birth","help":null,"required":true,"prefill":"child_dob"},{"id":"att_signature","type":"signature","label":"Parents signature","help":null,"required":true},{"id":"att_date","type":"date","label":"Date","help":null,"required":true,"prefill":"today"},{"id":"att_footer","type":"heading","label":"Attendance Policy 10/22","help":"Updated April 2026","required":false}]$pf$::jsonb, 'system'
WHERE NOT EXISTS (SELECT 1 FROM "PowerFormTemplates" WHERE name = $pf$Attendance Policies$pf$);
