SELECT $pf$Parental Consent to Use E-mail and/or Texting to Exchange Personally Identifiable Information & Photo release$pf$, NULL, $pf$[{"id":"eml_parent","type":"text","label":"Parent's Name","help":null,"required":true,"prefill":"parent_name","chart_field":"Parent_Name"},{"id":"eml_email","type":"email","label":"E-mail Address","help":null,"required":true,"prefill":"parent_email","chart_field":"Parent_Email"},{"id":"eml_cell","type":"phone","label":"Cell Phone","help":null,"required":true,"prefill":"parent_phone","chart_field":"Parent_Phone"},{"id":"eml_child","type":"text","label":"Child's Name","help":null,"required":true,"prefill":"child_name"},{"id":"eml_dob","type":"date","label":"D.O.B.","help":null,"required":true,"prefill":"child_dob"},{"id":"eml_risks","type":"heading","label":"Risks of using e-mail and text","help":"At your request, you have chosen to communicate personally identifiable information concerning your child's early intervention treatment by e-mail and/or text without the use of encryption. Sending personally identifiable information by e-mail has a number of risks that you should be aware of prior to giving your permission. These risks include, but are not limited to, the following:\n\n• E-mail and text can be forwarded and stored in electronic and paper format easily without prior knowledge of the parent.\n• E-mail or text senders can misaddress an e-mail or text and personally identifiable information can be sent to incorrect recipients by mistake.\n• E-mail sent over the Internet without encryption is not secure and can be intercepted by unknown third parties.\n• E-mail and text content can be changed without the knowledge of the sender or receiver.\n• Backup copies of e-mail and text messages may still exist even after the sender and receiver have deleted the messages.\n• Employers and online service providers have a right to check e-mail sent through their systems.\n• E-mail can contain harmful viruses and other programs.","required":false},{"id":"eml_ack","type":"heading","label":"Parental Acknowledgement and Agreement","help":"I acknowledge that I have read and understand the items above which describe the inherent risks of using e-mail and text messages to communicate personally identifiable information. Nevertheless, I authorize the below listed to communicate with me at my e-mail address and cell phone number listed above, concerning my child's participation in the Early Intervention Program (EIP), including but not limited to communication regarding service delivery, his/her progress in the EIP and any other related matters. I understand that use of e-mail without encryption presents the risks noted above and may result in an unintended disclosure of such information.","required":false},{"id":"eml_team_ok","type":"yesno","label":"I give permission for members of my child's treatment team to communicate personally identifiable information concerning my child with each other using unencrypted e-mail or texting.","help":"Early intervention team members who I give permission to use unencrypted e-mail or to text to communicate with each other about my child include:","required":true},{"id":"eml_team1_name","type":"text","label":"(1) Name","help":null,"required":false},{"id":"eml_team1_email","type":"email","label":"(1) at the e-mail address","help":null,"required":false},{"id":"eml_team1_phone","type":"phone","label":"(1) Phone to text","help":null,"required":false},{"id":"eml_team2_name","type":"text","label":"(2) Name","help":null,"required":false},{"id":"eml_team2_email","type":"email","label":"(2) at the e-mail address","help":null,"required":false},{"id":"eml_team2_phone","type":"phone","label":"(2) Phone to text","help":null,"required":false},{"id":"eml_team3_name","type":"text","label":"(3) Name","help":null,"required":false},{"id":"eml_team3_email","type":"email","label":"(3) at the e-mail address","help":null,"required":false},{"id":"eml_team3_phone","type":"phone","label":"(3) Phone to text","help":null,"required":false},{"id":"eml_signature","type":"signature","label":"Parent's Signature","help":null,"required":true},{"id":"eml_date","type":"date","label":"Date","help":null,"required":true,"prefill":"today"},{"id":"eml_photo","type":"yesno","label":"I give permission to use photographs/ videos of my child for promotional purposes.","help":null,"required":true,"chart_field":"Picture_Consent"},{"id":"eml_footer","type":"heading","label":"Email/txt/ photo consent 10/21","help":null,"required":false}]$pf$::jsonb, 'system'
WHERE NOT EXISTS (SELECT 1 FROM "PowerFormTemplates" WHERE name = $pf$Parental Consent to Use E-mail and/or Texting to Exchange Personally Identifiable Information & Photo release$pf$);
INSERT INTO "PowerFormTemplates" (name, intro, fields, created_by)
SELECT $pf$Parental Access To Child's Records$pf$, $pf$Early Intervention Officials and early intervention providers are required to ensure parents are afforded the opportunity to inspect and review all records pertaining to the child and the child's family that are maintained or used for the purposes of the Early Intervention Program (unless the parent is prohibited such access under State or federal law). It should be presumed that the parent has the authority to inspect and review early intervention records pertaining to his or her child unless the Early Intervention Official or early intervention service provider has been advised otherwise under applicable State law and regulations related to guardianship and custody. If a record contains information on more than one child or on non-participants, only the portion of the record pertaining to the child's participation in the EIP may be accessed.

The opportunity for parents to review and inspect early intervention records includes the right to:
• Receive an understandable explanation about and interpretations of information included in any early intervention record upon request.
• Obtain a copy of any early intervention record within 10 working days of receipt of the request by the Early Intervention Official or early intervention service provider.
• Obtain a copy of any early intervention record within 5 days if the request is made as part of a mediation or impartial hearing.
• Have a representative review the record on the parent's behalf.

All of the above rights extend to the commissioner of social services for children in the care and custody or custody and guardianship of the local social services districts.

Early Intervention Officials and early intervention providers have the following authority and responsibilities related to ensuring parental access to records:

• A reasonable fee may be charged to copy early intervention records upon parent request (not to exceed 10 cents per page for the first copy and 25 cents per page for additional copies), as long as the fee does not prevent the parent from inspecting and reviewing the record. No fees may be charged for records related to evaluations and assessments to which parents are specifically entitled (e.g., evaluation and assessment reports under 10 NYCRR § 69-4.8) unless specifically permitted.
• Parents may not be charged fees for the search and retrieval of early intervention records. Information about individual children/families included in any early intervention record should be able to be produced as a separate record, or with the names and identifying information of other children/families redacted (removed) from the documentation before it is shared with the parent.
• A record of all parties obtaining access to records gathered, maintained, or used for the purposes of the Early Intervention Program (except by parents and employees) must be maintained and must include the name of the party, date access was given, and the purpose for which the record was accessed.
• If a parent wished to have access to their child's record the following process will take place:

    1. Parents will call the service provider agency/ The Kidz Lounge and schedule an appointment to come and review their child's records. The agency and/or service coordinator will contact the rendering service provider if he/she continues to be employed by The Kidz Lounge. The parent must sign a request to be filed in the child's chart.
    2. Written parental consent must be obtained before personally identifiable information is disclosed to anyone other than authorized individuals. Written parental consent for release of or obtaining information must include the entity releasing and the entity obtaining the information; which records will be obtained or released; the purpose for the disclosure of information; the date the parent signed the consent; and the signature of the person in parental authority and their relationship to the child. Only information appropriate to a request should be released.
    3. One of the directors or service coordinator (if the rendering provider is not available) will assist the parent/caregiver if and will sign out the child's file and logs the date and reason for file review on the file sign-out sheet, located in the child's file. Where any part of the record contains information on more than one child, the parent shall only have the opportunity to review and inspect the portion of the record, which pertains to their child.
    4. HIV-related information can only be disclosed if the parent signs the New York State form for Release of Medical Information and Confidential HIV Related Information (DOH 2557). All written disclosures of confidential HIV information must be accompanied by a statement prohibiting re-disclosure. Frangelica Leo/Heather Hurley Cook are responsible for guaranteeing the confidentiality of sensitive information.
    5. The director or service coordinator (if the rendering provider is not available) will bring the child's file to a private setting for the parent and/or legal guardian to review, and remains in the room to answer any questions. In this way only information pertaining to the child/family who is the subject of a request for record access or disclosure is to be released. Identifiable information about other children receiving services is protected.
    6. The director or service coordinator (if the rendering provider is not available) provides the parent and/or legal guardian with copies within 10 business days, if requested.
        - If the child's record is requested as part of a mediation or impartial hearing, the record must be provided within 5 days of the request.
    7. The director or service coordinator (if the rendering provider is not available) returns the child's file to the file cabinet.

• Parents have the right to request an amendment to their child's record when the parent believes the information contained in the record is inaccurate, misleading or violates the privacy or any other rights of their child. When such a request for an amendment to their child's record is made, a decision will be made based on a review of all the information available. If information is found to be inaccurate, misleading or to violate the privacy of the child/family, changes are to be made as soon as possible. The provider will amend the information and will inform the family's service coordinator immediately. Amended copies will be sent to the service coordinator. The service coordinator will notify the parent in writing of the amendment.
• If the provider decides not to amend the records as requested, the provider informs the Service Coordinator and agency supervisor of this decision who in turn notifies the EIOD. The EIOD informs the parent in writing of the decision not to amend the record, and that the parent has the right to a hearing. The hearing will be conducted by an individual designated by the municipality, who does not have direct interest in the outcome of the hearing.
• Please note: The agency Director Frangelica Leo and/or CEO Heather Hurley Cook is responsible for guaranteeing the confidentiality of sensitive information.

** Keep this for your records$pf$, $pf$[{"id":"rec_ack","type":"heading","label":"Acknowledgement","help":"I have read and understand my rights as a parent/legal guardian to have access to my child's records as described by The Kidz Lounge in the letter entitled “Parental Access Children's Records”.","required":false},{"id":"rec_child","type":"text","label":"Childs Name","help":null,"required":true,"prefill":"child_name"},{"id":"rec_dob","type":"date","label":"Date of Birth","help":null,"required":true,"prefill":"child_dob"},{"id":"rec_signature","type":"signature","label":"Signed","help":null,"required":true},{"id":"rec_date","type":"date","label":"Date","help":null,"required":true,"prefill":"today"},{"id":"rec_relationship","type":"text","label":"Relationship to child","help":null,"required":true,"prefill":"relationship","chart_field":"Relationship_To_Patient"},{"id":"rec_footer","type":"heading","label":"** Send back to The Kidz Lounge","help":null,"required":false}]$pf$::jsonb, 'system'
WHERE NOT EXISTS (SELECT 1 FROM "PowerFormTemplates" WHERE name = $pf$Parental Access To Child's Records$pf$);
