SELECT $pf$NYC Early Intervention Program Consent to Release/Obtain Information$pf$, NULL, $pf$[{"id":"rel_child","type":"text","label":"Child's Name","help":null,"required":true,"prefill":"child_name"},{"id":"rel_ei","type":"text","label":"EI #","help":null,"required":true,"prefill":"ei_number"},{"id":"rel_dob","type":"date","label":"DOB","help":null,"required":true,"prefill":"child_dob"},{"id":"rel_address","type":"text","label":"Address","help":null,"required":true,"prefill":"address"},{"id":"rel_apt","type":"text","label":"Apt #","help":null,"required":false,"prefill":"address_line2"},{"id":"rel_city","type":"text","label":"City/Town","help":null,"required":true,"prefill":"city"},{"id":"rel_state","type":"text","label":"State","help":null,"required":true,"default":"New York","prefill":"state"},{"id":"rel_zip","type":"text","label":"Zip Code","help":null,"required":true,"prefill":"zip"},{"id":"rel_parent","type":"text","label":"I, (Parent/Guardian's Full Name)","help":"seek services for my child from the NYC Early Intervention Program. I understand that the providers (including evaluators, service providers and service coordinators) offering Early Intervention (EI) services to my child and family may need to exchange information to develop and carry out the Individualized Family Service Plan (IFSP).","required":true,"prefill":"parent_name"},{"id":"rel_direction","type":"choice","label":"(Check one)","help":null,"required":true,"options":["I authorize for the information below to be released","I authorize for the information below to be obtained"],"default":"I authorize for the information below to be released"},{"id":"rel_info","type":"checkboxes","label":"Specific information to be released/obtained:","help":null,"required":true,"options":["EI Medical Form","Multidisciplinary Evaluation","Supplemental Evaluation(s)","Individualized Family Service Plan","Provider Progress Notes","Session Notes","Other"],"default":["EI Medical Form","Multidisciplinary Evaluation","Supplemental Evaluation(s)","Individualized Family Service Plan","Provider Progress Notes","Session Notes"]},{"id":"rel_supplemental","type":"text","label":"Supplemental Evaluation(s) Specify:","help":null,"required":false},{"id":"rel_info_other","type":"text","label":"Other:","help":null,"required":false},{"id":"rel_abc","type":"checkboxes","label":"I authorize for the information to be (check/complete either A, B, or C):","help":null,"required":true,"options":["A. Released to all EI providers providing evaluation, service coordination, or services to my child and family","B. Released to the Individual/Agency below","C. Obtained from the Individual/Agency below"],"default":["A. Released to all EI providers providing evaluation, service coordination, or services to my child and family","B. Released to the Individual/Agency below"]},{"id":"rel_b_h","type":"heading","label":"B. Released to the Individual/Agency below:","help":null,"required":false},{"id":"rel_b_name","type":"text","label":"(Name/ Organization)","help":null,"required":false,"default":"The Kidz Lounge Related Services"},{"id":"rel_b_address","type":"text","label":"(Street Address, Borough/City, Zip Code)","help":null,"required":false,"default":"8212 151st Ave. Howard Beach, NY 11414"},{"id":"rel_b_phone","type":"phone","label":"(Telephone Number)","help":null,"required":false,"default":"(718) 848-0875"},{"id":"rel_b_fax","type":"phone","label":"(Fax Number)","help":null,"required":false},{"id":"rel_c_h","type":"heading","label":"C. Obtained from the Individual/Agency below:","help":null,"required":false},{"id":"rel_c_name","type":"text","label":"(Name/ Organization)","help":null,"required":false},{"id":"rel_c_address","type":"text","label":"(Street Address, Borough/City, Zip Code)","help":null,"required":false},{"id":"rel_c_phone","type":"phone","label":"(Telephone Number)","help":null,"required":false},{"id":"rel_c_fax","type":"phone","label":"(Fax Number)","help":null,"required":false},{"id":"rel_to_h","type":"heading","label":"The information will be sent to:","help":null,"required":false},{"id":"rel_to_name","type":"text","label":"(Name/ Organization)","help":null,"required":false},{"id":"rel_to_address","type":"text","label":"(Street Address, Borough/City, Zip Code)","help":null,"required":false},{"id":"rel_to_phone","type":"phone","label":"(Telephone Number)","help":null,"required":false},{"id":"rel_to_fax","type":"phone","label":"(Fax Number)","help":null,"required":false},{"id":"rel_purpose","type":"checkboxes","label":"D. The purpose of the requested information is to: (check all that apply)","help":null,"required":false,"options":["Establish Early Intervention eligibility","Develop an Individualized Family Service Plan","Start, coordinate and monitor Early Intervention services","Inform the child's physician about my child's services and","Other"]},{"id":"rel_purpose_other","type":"text","label":"Other:","help":null,"required":false},{"id":"rel_ends","type":"date","label":"This release ends on the date of my next scheduled IFSP (or, if sooner, specify date)","help":"I understand that this release can be withdrawn at any time upon written notice to my Service Coordinator.","required":false},{"id":"rel_signature","type":"signature","label":"Signed","help":null,"required":true},{"id":"rel_relationship","type":"text","label":"Relationship to Child","help":null,"required":true,"prefill":"relationship","chart_field":"Relationship_To_Patient"},{"id":"rel_date","type":"date","label":"Date","help":null,"required":true,"prefill":"today"},{"id":"rel_note","type":"heading","label":"NOTE","help":"A reproduced copy of this signed form is deemed to have the same force and effect as the original. A new Consent to Release Information form must be signed at the initial IFSP meeting and at each IFSP review and annual meeting. Blank consent forms should never be signed by the parent.\n\nConsent to Release/Obtain Information Revised 12/10","required":false}]$pf$::jsonb, 'system'
WHERE NOT EXISTS (SELECT 1 FROM "PowerFormTemplates" WHERE name = $pf$NYC Early Intervention Program Consent to Release/Obtain Information$pf$);
INSERT INTO "PowerFormPackages" (name, template_ids, created_by)
SELECT $pf$Initial Clearance Forms$pf$, (
  SELECT jsonb_agg(t.id ORDER BY o.n) FROM (VALUES (0, $pf$Attendance Policies$pf$), (1, $pf$Permission to Request Doctor Prescription for Services$pf$), (2, $pf$Parental Consent to Use E-mail and/or Texting to Exchange Personally Identifiable Information & Photo release$pf$), (3, $pf$Parental Access To Child's Records$pf$), (4, $pf$NYC Early Intervention Program Consent to Release/Obtain Information$pf$)) AS o(n, name)
  JOIN LATERAL (SELECT id FROM "PowerFormTemplates" WHERE name = o.name ORDER BY id LIMIT 1) t ON true
), 'system'
WHERE NOT EXISTS (SELECT 1 FROM "PowerFormPackages" WHERE name = $pf$Initial Clearance Forms$pf$);
